const ADMIN_EMAIL = '';
const HOJA_USUARIOS = 'Usuarios';
const LOGO_ID = '18lFx6L5qOy2hYPAua7yFZt56vx1mTPor';

const DURACION_CODIGO = 300;
const DURACION_SESION = 21600;

const MAX_INTENTOS = 5;
const BLOQUEO_LOGIN = 900;
const RONDAS_HASH = 1000;
const MAX_CODIGOS_POR_HORA = 10;

const REGEX_NOMBRE =
  /^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+(?:[ '\-][A-Za-zÁÉÍÓÚÜÑáéíóúüñ]+)*$/;

const REGEX_CORREO =
  /^[A-Za-z0-9][A-Za-z0-9._%+\-]*@[A-Za-z0-9\-]+(?:\.[A-Za-z0-9\-]+)*\.[A-Za-z]{2,}$/;

function doGet(e) {
  const pagina = e && e.parameter
    ? String(e.parameter.pagina || '').toLowerCase()
    : '';

  const archivo = pagina === 'consultas'
    ? 'consultas'
    : 'admin';

  return HtmlService
    .createHtmlOutputFromFile(archivo)
    .setTitle(
      pagina === 'consultas'
        ? 'Consultas | Sistema Telmex'
        : 'Administración | Sistema Telmex'
    )
    .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}
function obtenerUrlApp() {
  const url = ScriptApp.getService().getUrl();

  if (!url) {
    throw new Error(
      'No se encontró la URL publicada. Implementa el proyecto como aplicación web.'
    );
  }

  return url;
}

function obtenerUrlSalidaConsultas() {
  return obtenerUrlApp();
}

function obtenerLogo() {
  try {
    const blob = DriveApp.getFileById(LOGO_ID).getBlob();

    return 'data:' + blob.getContentType() + ';base64,' +
      Utilities.base64Encode(blob.getBytes());

  } catch (error) {
    console.error('Error al obtener el logotipo:', error);
    return '';
  }
}

function obtenerSpreadsheet_() {
  const activa = SpreadsheetApp.getActiveSpreadsheet();

  if (activa) {
    return activa;
  }

  const propiedades = PropertiesService.getScriptProperties();
  const id = propiedades.getProperty('SPREADSHEET_ID');

  if (id) {
    try {
      return SpreadsheetApp.openById(id);
    } catch (error) {
      console.error(
        'No se pudo abrir la hoja configurada:',
        error.message
      );

      throw new Error(
        'No se pudo abrir la hoja de cálculo configurada. ' +
        'Revisa el ID y los permisos del proyecto.'
      );
    }
  }

  const ss = SpreadsheetApp.create('Sistema de usuarios Telmex');

  propiedades.setProperty('SPREADSHEET_ID', ss.getId());

  return ss;
}


/**
 * Obtiene o crea la pestaña Usuarios.
 */
function obtenerHojaUsuarios_() {
  const ss = obtenerSpreadsheet_();

  let hoja = ss.getSheetByName(HOJA_USUARIOS);

  if (!hoja) {
    hoja = ss.insertSheet(HOJA_USUARIOS);
  }

  if (hoja.getLastRow() === 0) {
    hoja.appendRow([
      'ID',
      'Nombre',
      'Correo',
      'Salt',
      'Hash',
      'Rol',
      'Estado',
      'Fecha de registro'
    ]);

    hoja.setFrozenRows(1);
    hoja.getRange(1, 1, 1, 8).setFontWeight('bold');
  }

  return hoja;
}


/**
 * Agrega una fila a la hoja Usuarios.
 */
function agregarFila_(valores) {
  const hoja = obtenerHojaUsuarios_();
  const fila = hoja.getLastRow() + 1;

  if (fila > hoja.getMaxRows()) {
    hoja.insertRowsAfter(hoja.getMaxRows(), 1);
  }

  const rango = hoja.getRange(fila, 1, 1, valores.length);

  rango.setNumberFormats([
    valores.map(function(valor) {
      return valor instanceof Date
        ? 'yyyy-mm-dd hh:mm:ss'
        : '@';
    })
  ]);

  rango.setValues([valores]);
}


/**
 * Inicializa la hoja de cálculo.
 * Puedes ejecutar esta función manualmente desde el editor.
 */
function configurarSistema() {
  const hoja = obtenerHojaUsuarios_();
  const ss = obtenerSpreadsheet_();

  Logger.log('URL de la hoja: ' + ss.getUrl());
  Logger.log('Pestaña: ' + hoja.getName());

  return {
    mensaje: 'Sistema configurado correctamente.',
    urlHoja: ss.getUrl(),
    nombreHoja: hoja.getName()
  };
}


/**
 * Devuelve el enlace a la hoja de usuarios exclusivamente
 * a administradores autenticados.
 */
function obtenerUrlHojaUsuarios(token) {
  const sesion = obtenerSesion_(token);

  if (sesion.rol !== 'administrador') {
    throw new Error('Acceso denegado.');
  }

  return obtenerSpreadsheet_().getUrl();
}


/* =========================================================
   VALIDACIONES
   ========================================================= */


/**
 * Normaliza el correo.
 */
function normalizarCorreo_(correo) {
  return String(correo || '').trim().toLowerCase();
}


/**
 * Valida nombres.
 */
function validarNombre_(nombre) {
  nombre = String(nombre || '').trim().replace(/\s+/g, ' ');

  if (nombre.length < 2 || nombre.length > 100) {
    throw new Error(
      'El nombre debe tener entre 2 y 100 caracteres.'
    );
  }

  if (!REGEX_NOMBRE.test(nombre)) {
    throw new Error(
      'El nombre solo puede contener letras, espacios, guiones y apóstrofos.'
    );
  }

  return nombre;
}


/**
 * Valida y normaliza correos electrónicos.
 */
function validarCorreo_(correo) {
  correo = normalizarCorreo_(correo);

  if (correo.length > 254 || !REGEX_CORREO.test(correo)) {
    throw new Error(
      'Escribe un correo válido, por ejemplo usuario@dominio.com.'
    );
  }

  return correo;
}


/**
 * Valida contraseñas.
 */
function validarPassword_(password) {
  password = String(password || '');

  if (password.length < 12 || password.length > 128) {
    throw new Error(
      'La contraseña debe tener entre 12 y 128 caracteres.'
    );
  }

  if (/[\u0000-\u001F\u007F]/.test(password)) {
    throw new Error(
      'La contraseña contiene caracteres no permitidos.'
    );
  }

  return password;
}


/**
 * Si ADMIN_EMAIL está configurado, únicamente ese correo
 * podrá registrar al administrador inicial.
 */
function verificarCorreoPermitido_(correo) {
  const permitido = normalizarCorreo_(ADMIN_EMAIL);

  if (permitido && correo !== permitido) {
    throw new Error(
      'Este correo no está autorizado para registrar al administrador inicial.'
    );
  }
}


/* =========================================================
   CONTRASEÑAS Y CÓDIGOS
   ========================================================= */


/**
 * Calcula el hash de la contraseña con salt.
 */
function calcularHash_(password, salt) {
  let valor = salt + String(password);

  for (let i = 0; i < RONDAS_HASH; i++) {
    const bytes = Utilities.computeDigest(
      Utilities.DigestAlgorithm.SHA_256,
      valor + salt,
      Utilities.Charset.UTF_8
    );

    valor = Utilities.base64Encode(bytes);
  }

  return valor;
}


/**
 * Genera un código numérico de seis dígitos.
 */
function generarCodigoSeguro_() {
  const bytes = Utilities.computeDigest(
    Utilities.DigestAlgorithm.SHA_256,
    Utilities.getUuid() + Utilities.getUuid(),
    Utilities.Charset.UTF_8
  );

  let numero = 0;

  for (let i = 0; i < 4; i++) {
    numero = numero * 256 + (bytes[i] & 255);
  }

  return String(numero % 1000000).padStart(6, '0');
}


/* =========================================================
   BÚSQUEDA DE USUARIOS
   ========================================================= */


/**
 * Busca un usuario por correo electrónico.
 */
function buscarUsuarioPorCorreo_(correo) {
  const datos = obtenerHojaUsuarios_().getDataRange().getValues();
  const buscado = normalizarCorreo_(correo);

  for (let i = 1; i < datos.length; i++) {
    if (normalizarCorreo_(datos[i][2]) === buscado) {
      return {
        fila: i + 1,
        id: String(datos[i][0]),
        nombre: String(datos[i][1] || ''),
        correo: normalizarCorreo_(datos[i][2]),
        salt: String(datos[i][3] || ''),
        hash: String(datos[i][4] || ''),
        rol: String(datos[i][5] || '').trim().toLowerCase(),
        estado: String(datos[i][6] || '').trim().toLowerCase()
      };
    }
  }

  return null;
}


/**
 * Busca un usuario por su ID.
 */
function buscarUsuarioPorId_(id) {
  const datos = obtenerHojaUsuarios_().getDataRange().getValues();
  const buscado = String(id || '').trim();

  for (let i = 1; i < datos.length; i++) {
    if (String(datos[i][0]) === buscado) {
      return {
        fila: i + 1,
        id: String(datos[i][0]),
        nombre: String(datos[i][1] || ''),
        correo: normalizarCorreo_(datos[i][2]),
        rol: String(datos[i][5] || '').trim().toLowerCase(),
        estado: String(datos[i][6] || '').trim().toLowerCase()
      };
    }
  }

  return null;
}


/**
 * Comprueba si existe un administrador.
 */
function existeAdministrador() {
  const datos = obtenerHojaUsuarios_().getDataRange().getValues();

  for (let i = 1; i < datos.length; i++) {
    if (
      String(datos[i][5]).trim().toLowerCase() === 'administrador'
    ) {
      return true;
    }
  }

  return false;
}


/**
 * Cuenta administradores activos.
 */
function contarAdministradoresActivos_() {
  const datos = obtenerHojaUsuarios_().getDataRange().getValues();

  let total = 0;

  for (let i = 1; i < datos.length; i++) {
    if (
      String(datos[i][5]).trim().toLowerCase() === 'administrador' &&
      String(datos[i][6]).trim().toLowerCase() === 'activo'
    ) {
      total++;
    }
  }

  return total;
}


/* =========================================================
   REGISTRO DEL ADMINISTRADOR INICIAL
   ========================================================= */


/**
 * Envía el código de verificación al correo que se registrará
 * como administrador inicial.
 */
function enviarCodigoAdministrador(nombre, correo, password) {
  nombre = validarNombre_(nombre);
  correo = validarCorreo_(correo);
  password = validarPassword_(password);

  verificarCorreoPermitido_(correo);

  if (existeAdministrador()) {
    throw new Error(
      'El administrador inicial ya fue registrado.'
    );
  }

  const cache = CacheService.getScriptCache();
  const bloqueo = 'bloqueo_codigo_' + correo;

  if (cache.get(bloqueo)) {
    throw new Error(
      'Espera un minuto antes de solicitar otro código.'
    );
  }

  const enviados = Number(
    cache.get('envios_codigo_global') || 0
  );

  if (enviados >= MAX_CODIGOS_POR_HORA) {
    throw new Error(
      'Demasiadas solicitudes. Intenta más tarde.'
    );
  }

  const codigo = generarCodigoSeguro_();
  const salt = Utilities.getUuid();

  const pendiente = {
    nombre: nombre,
    correo: correo,
    salt: salt,
    hash: calcularHash_(password, salt)
  };

  // Guardar la solicitud temporal.
  cache.put(
    'codigo_admin_' + correo,
    codigo,
    DURACION_CODIGO
  );

  cache.put(
    'pendiente_admin_' + correo,
    JSON.stringify(pendiente),
    DURACION_CODIGO
  );

  cache.remove('intentos_codigo_' + correo);

  try {
    MailApp.sendEmail({
      to: correo,
      subject: 'Código de verificación - Sistema Telmex',
      body:
        'Tu código de verificación es: ' + codigo +
        '\n\nCaduca en 5 minutos.' +
        '\nSi no solicitaste este código, ignora este mensaje.'
    });

    cache.put(
      'envios_codigo_global',
      String(enviados + 1),
      3600
    );

    cache.put(bloqueo, '1', 55);

  } catch (error) {
    cache.remove('codigo_admin_' + correo);
    cache.remove('pendiente_admin_' + correo);
    cache.remove(bloqueo);

    throw new Error(
      'No se pudo enviar el correo: ' + error.message
    );
  }

  return 'Código enviado a ' + correo +
    '. Revisa tu bandeja de entrada y spam.';
}


/**
 * Verifica el código y registra al administrador inicial.
 */
function verificarCodigoAdministrador(correo, codigo) {
  correo = validarCorreo_(correo);
  codigo = String(codigo || '').trim();

  verificarCorreoPermitido_(correo);

  if (!/^\d{6}$/.test(codigo)) {
    throw new Error(
      'Escribe el código de seis dígitos.'
    );
  }

  const cache = CacheService.getScriptCache();

  const claveCodigo = 'codigo_admin_' + correo;
  const clavePendiente = 'pendiente_admin_' + correo;
  const claveIntentos = 'intentos_codigo_' + correo;

  const codigoGuardado = cache.get(claveCodigo);
  const pendienteTexto = cache.get(clavePendiente);

  if (!codigoGuardado || !pendienteTexto) {
    throw new Error(
      'El código caducó. Solicita uno nuevo.'
    );
  }

  const intentos = Number(
    cache.get(claveIntentos) || 0
  );

  if (intentos >= MAX_INTENTOS) {
    cache.remove(claveCodigo);
    cache.remove(clavePendiente);
    cache.remove(claveIntentos);

    throw new Error(
      'Demasiados intentos. Solicita un código nuevo.'
    );
  }

  if (codigo !== codigoGuardado) {
    cache.put(
      claveIntentos,
      String(intentos + 1),
      DURACION_CODIGO
    );

    throw new Error('Código incorrecto.');
  }

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);

  try {
    if (existeAdministrador()) {
      throw new Error(
        'El administrador ya fue registrado.'
      );
    }

    const pendiente = JSON.parse(pendienteTexto);

    agregarFila_([
      Utilities.getUuid(),
      pendiente.nombre,
      pendiente.correo,
      pendiente.salt,
      pendiente.hash,
      'administrador',
      'activo',
      new Date()
    ]);

    cache.remove(claveCodigo);
    cache.remove(clavePendiente);
    cache.remove(claveIntentos);

    return crearSesion_(
      pendiente.correo,
      'administrador',
      pendiente.nombre
    );

  } finally {
    lock.releaseLock();
  }
}


/* =========================================================
   INICIO DE SESIÓN
   ========================================================= */


/**
 * Valida el correo y la contraseña y crea una sesión.
 */
function iniciarSesion(correo, password) {
  correo = validarCorreo_(correo);
  password = String(password || '');

  if (!password || password.length > 128) {
    throw new Error(
      'Escribe tu correo y contraseña.'
    );
  }

  const cache = CacheService.getScriptCache();
  const claveFallos = 'fallos_login_' + correo;

  const fallos = Number(
    cache.get(claveFallos) || 0
  );

  if (fallos >= MAX_INTENTOS) {
    throw new Error(
      'Demasiados intentos. Espera 15 minutos.'
    );
  }

  const usuario = buscarUsuarioPorCorreo_(correo);
  const generico = 'Credenciales incorrectas o cuenta inactiva.';

  if (!usuario || usuario.estado !== 'activo') {
    cache.put(
      claveFallos,
      String(fallos + 1),
      BLOQUEO_LOGIN
    );

    throw new Error(generico);
  }

  const hashIngresado = calcularHash_(
    password,
    usuario.salt
  );

  if (hashIngresado !== usuario.hash) {
    cache.put(
      claveFallos,
      String(fallos + 1),
      BLOQUEO_LOGIN
    );

    throw new Error(generico);
  }

  cache.remove(claveFallos);

  return crearSesion_(
    usuario.correo,
    usuario.rol,
    usuario.nombre
  );
}


/* =========================================================
   CREACIÓN Y VALIDACIÓN DE SESIONES
   ========================================================= */


/**
 * Crea una sesión temporal.
 */
function crearSesion_(correo, rol, nombre) {
  const token = Utilities.getUuid() + Utilities.getUuid();

  CacheService.getScriptCache().put(
    'sesion_' + token,
    JSON.stringify({
      correo: normalizarCorreo_(correo),
      rol: String(rol || '').trim().toLowerCase()
    }),
    DURACION_SESION
  );

  return {
    token: token,
    nombre: nombre,
    rol: String(rol || '').trim().toLowerCase()
  };
}


/**
 * Comprueba que el token corresponda a una sesión vigente.
 * También verifica que la cuenta siga activa y conserve su rol.
 */
function obtenerSesion_(token) {
  token = String(token || '');

  if (!/^[a-f0-9-]{72}$/i.test(token)) {
    throw new Error(
      'Sesión no válida. Inicia sesión nuevamente.'
    );
  }

  const cache = CacheService.getScriptCache();
  const claveSesion = 'sesion_' + token;
  const valor = cache.get(claveSesion);

  if (!valor) {
    throw new Error(
      'La sesión caducó. Inicia sesión nuevamente.'
    );
  }

  const sesion = JSON.parse(valor);
  const usuario = buscarUsuarioPorCorreo_(sesion.correo);

  if (
    !usuario ||
    usuario.estado !== 'activo' ||
    usuario.rol !== sesion.rol
  ) {
    cache.remove(claveSesion);

    throw new Error(
      'La cuenta ya no tiene acceso.'
    );
  }

  return sesion;
}


/**
 * Invalida la sesión.
 */
function cerrarSesion(token) {
  token = String(token || '');

  if (!/^[a-f0-9-]{72}$/i.test(token)) {
    return true;
  }

  CacheService.getScriptCache().remove(
    'sesion_' + token
  );

  return true;
}


/* =========================================================
   CREAR USUARIOS
   ========================================================= */


/**
 * Solo un administrador autenticado puede crear usuarios.
 *
 * Roles permitidos:
 * - consulta
 * - administrador
 */
function crearUsuario(token, nombre, correo, password, rol) {
  const sesion = obtenerSesion_(token);

  if (sesion.rol !== 'administrador') {
    throw new Error(
      'No tienes permisos para registrar usuarios.'
    );
  }

  nombre = validarNombre_(nombre);
  correo = validarCorreo_(correo);
  password = validarPassword_(password);

  rol = String(rol || '').trim().toLowerCase();

  if (!['consulta', 'administrador'].includes(rol)) {
    throw new Error('Rol no permitido.');
  }

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);

  try {
    if (buscarUsuarioPorCorreo_(correo)) {
      throw new Error(
        'Ya existe una cuenta con ese correo.'
      );
    }

    const salt = Utilities.getUuid();

    agregarFila_([
      Utilities.getUuid(),
      nombre,
      correo,
      salt,
      calcularHash_(password, salt),
      rol,
      'activo',
      new Date()
    ]);

  } finally {
    lock.releaseLock();
  }

  return 'Usuario registrado correctamente.';
}


/* =========================================================
   LISTAR USUARIOS
   ========================================================= */


/**
 * Devuelve usuarios sin exponer salts ni hashes.
 */
function listarUsuarios(token) {
  const sesion = obtenerSesion_(token);

  if (sesion.rol !== 'administrador') {
    throw new Error('Acceso denegado.');
  }

  const datos = obtenerHojaUsuarios_()
    .getDataRange()
    .getValues();

  return datos.slice(1)
    .filter(function(fila) {
      return fila[0] !== '' && fila[0] != null;
    })
    .map(function(fila) {
      return {
        id: String(fila[0]),
        nombre: String(fila[1] || ''),
        correo: String(fila[2] || ''),
        rol: String(fila[5] || '').trim().toLowerCase(),
        estado: String(fila[6] || '').trim().toLowerCase()
      };
    });
}


/* =========================================================
   EDITAR USUARIOS
   ========================================================= */


/**
 * Permite editar nombre, correo, rol y estado.
 * No permite editar la propia cuenta desde esta función.
 */
function editarUsuario(token, id, nombre, correo, rol, estado) {
  const sesion = obtenerSesion_(token);

  if (sesion.rol !== 'administrador') {
    throw new Error(
      'No tienes permisos para editar usuarios.'
    );
  }

  nombre = validarNombre_(nombre);
  correo = validarCorreo_(correo);

  rol = String(rol || '').trim().toLowerCase();
  estado = String(estado || '').trim().toLowerCase();

  if (!['consulta', 'administrador'].includes(rol)) {
    throw new Error(
      'El rol seleccionado no es válido.'
    );
  }

  if (!['activo', 'inactivo'].includes(estado)) {
    throw new Error(
      'El estado seleccionado no es válido.'
    );
  }

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);

  try {
    const actual = buscarUsuarioPorId_(id);

    if (!actual) {
      throw new Error(
        'El usuario ya no existe.'
      );
    }

    if (actual.correo === sesion.correo) {
      throw new Error(
        'No puedes editar tu propia cuenta desde esta pantalla.'
      );
    }

    const existente = buscarUsuarioPorCorreo_(correo);

    if (existente && existente.id !== String(id)) {
      throw new Error(
        'Ya existe otro usuario con ese correo.'
      );
    }

    const seQuitaraAdmin =
      actual.rol === 'administrador' &&
      actual.estado === 'activo' &&
      (rol !== 'administrador' || estado !== 'activo');

    if (
      seQuitaraAdmin &&
      contarAdministradoresActivos_() <= 1
    ) {
      throw new Error(
        'No puedes quitar o desactivar al último administrador activo.'
      );
    }

    const hoja = obtenerHojaUsuarios_();

    hoja.getRange(actual.fila, 2, 1, 2)
      .setNumberFormat('@')
      .setValues([[nombre, correo]]);

    hoja.getRange(actual.fila, 6, 1, 2)
      .setNumberFormat('@')
      .setValues([[rol, estado]]);

  } finally {
    lock.releaseLock();
  }

  return 'Los datos del usuario se actualizaron correctamente.';
}


/* =========================================================
   ELIMINAR USUARIOS
   ========================================================= */


/**
 * Solo un administrador puede eliminar usuarios.
 * No permite eliminar la propia cuenta ni al último
 * administrador activo.
 */
function eliminarUsuario(token, id) {
  const sesion = obtenerSesion_(token);

  if (sesion.rol !== 'administrador') {
    throw new Error(
      'No tienes permisos para eliminar usuarios.'
    );
  }

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);

  try {
    const usuario = buscarUsuarioPorId_(id);

    if (!usuario) {
      throw new Error(
        'El usuario no existe o ya fue eliminado.'
      );
    }

    if (usuario.correo === sesion.correo) {
      throw new Error(
        'No puedes eliminar tu propia cuenta.'
      );
    }

    if (
      usuario.rol === 'administrador' &&
      usuario.estado === 'activo' &&
      contarAdministradoresActivos_() <= 1
    ) {
      throw new Error(
        'No puedes eliminar al último administrador activo.'
      );
    }

    obtenerHojaUsuarios_().deleteRow(usuario.fila);

  } finally {
    lock.releaseLock();
  }

  return 'El usuario se eliminó correctamente.';
}


/* =========================================================
   CONSULTAS
   ========================================================= */


/**
 * Permite el acceso a consultas a ambos roles:
 * - consulta
 * - administrador
 *
 * La sesión y el estado de la cuenta se verifican
 * en el servidor antes de devolver información.
 */
function obtenerConsultas(token) {
  const sesion = obtenerSesion_(token);

  if (!['consulta', 'administrador'].includes(sesion.rol)) {
    throw new Error(
      'No tienes permisos para acceder a consultas.'
    );
  }

  return {
    mensaje: sesion.rol === 'administrador'
      ? 'Acceso autorizado a las consultas como administrador.'
      : 'Acceso autorizado a las consultas.',
    fecha: new Date().toLocaleString('es-MX'),
    rol: sesion.rol
  };
}


/* =========================================================
   MIGRACIÓN DE ROLES ANTIGUOS
   Ejecutar manualmente solo si existen cuentas operador.
   ========================================================= */


/**
 * Convierte el rol antiguo operador a consulta.
 */
function migrarRolesAntiguos() {
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);

  try {
    const hoja = obtenerHojaUsuarios_();
    const ultimaFila = hoja.getLastRow();

    if (ultimaFila < 2) {
      return 'No hay usuarios que actualizar.';
    }

    const rango = hoja.getRange(2, 6, ultimaFila - 1, 1);
    const valores = rango.getValues();

    let modificados = 0;

    valores.forEach(function(fila) {
      if (
        String(fila[0]).trim().toLowerCase() === 'operador'
      ) {
        fila[0] = 'consulta';
        modificados++;
      }
    });

    rango.setValues(valores);

    return 'Migración terminada. Cuentas convertidas a consulta: ' +
      modificados + '.';

  } finally {
    lock.releaseLock();
  }
}


