/**
 * Envía un correo de prueba a la cuenta que ejecuta
 * esta función.
 */
function diagnosticarCorreo() {
  const destino = Session.getEffectiveUser().getEmail();

  if (!destino) {
    throw new Error(
      'No se pudo identificar el correo de la cuenta que ejecuta el script.'
    );
  }

  Logger.log(
    'Cuota de correos restante hoy: ' +
    MailApp.getRemainingDailyQuota()
  );

  MailApp.sendEmail({
    to: destino,
    subject: 'Prueba - Sistema Telmex',
    body: 'Si lees esto, el envío de correo funciona.'
  });

  Logger.log(
    'Correo de prueba enviado a ' + destino
  );

  return 'Correo de prueba enviado a ' + destino;
}
